# Homebrew formula for forgeo.
#
# This file is generated by the release pipeline in the forgeo repository
# (.github/workflows/ci.yml, publish-homebrew job): every new tag vX.Y.Z
# downloads the prebuilt binaries, computes their sha256 and updates this
# formula. Do not edit by hand; re-run the pipeline instead.

class Forgeo < Formula
  desc "A scheduled software forgeo: executes backlog tasks on main, refactors when idle, and writes BLOCKER.md when it needs human input."
  homepage "https://forgeo.org"
  version "0.4.0"
  license "MIT"

  url "https://github.com/lucaGazzola/forgeo/releases/download/v0.4.0/forgeo-linux-amd64"

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/lucaGazzola/forgeo/releases/download/v0.4.0/forgeo-darwin-arm64"
      sha256 "bd4bf615e6444df207baca3702ca69ff0887b8ab4bbc09fdb85030fe8a5d1e2c"
    else
      url "https://github.com/lucaGazzola/forgeo/releases/download/v0.4.0/forgeo-darwin-amd64"
      sha256 "7db080dc573d92e27639d63536bc283ff3be2a4710ab6b384c6c3dfb3e67a16b"
    end
  end

  on_linux do
    if Hardware::CPU.intel?
      url "https://github.com/lucaGazzola/forgeo/releases/download/v0.4.0/forgeo-linux-amd64"
      sha256 "fc1f732fd06383ffa6fc6913524801bf8ff6aa20c7db9b576299859f39381c5d"
    end
  end

  def install
    binary = Pathname.glob("forgeo-*").first
    bin.install binary => "forgeo"
  end

  test do
    assert_match "forgeo #{version}", shell_output("#{bin}/forgeo --version")
  end
end
